// ============================================================
// DSE Mini Mock — Style Library
// ============================================================

#let ML = 20mm
#let MT = 18mm

// ------------------------------------------------------------
// ANSWER SPACE  (generates ruled lines, default 5)
// ------------------------------------------------------------
#let answer-space(n: 5) = {
  for _ in range(n) {
    line(length: 100%, stroke: (thickness: 0.4pt, paint: gray, dash: "dotted"))
    v(3mm)
  }
}

// ------------------------------------------------------------
// QUESTION FORMATTER
// ------------------------------------------------------------
#let fmt-question(qnum, marks, body) = {
  [
    #text(size: 10pt, font: "Times New Roman", weight: "bold")[
      Q#{qnum}.
    ]
    #body
    #h(1fr)
    #text(size: 9pt, font: "Times New Roman")[(#{marks} marks)]
    #v(4mm)
    #answer-space(n: if marks <= 3 { 4 } else if marks <= 5 { 5 } else { 6 })
  ]
}

// ------------------------------------------------------------
// SECTION HEADER
// ------------------------------------------------------------
#let fmt-section-header(section-label, section-marks) = {
  [
    #v(3mm)
    #text(size: 11pt, font: "Times New Roman", weight: "bold")[
      Section #{section-label} (#{section-marks} marks)
    ]
    #v(2mm)
    #line(length: 100%, stroke: (thickness: 0.8pt, paint: black))
    #v(2mm)
  ]
}

// ------------------------------------------------------------
// COVER PAGE
// ------------------------------------------------------------
#let fmt-cover = {
  page(
    paper: "a4",
    margin: (top: MT, bottom: MT, left: ML, right: ML),
    header: none,
    footer: none,
  )[
    #v(10mm)

    #align(center)[
      #text(size: 18pt, font: "Times New Roman", weight: "bold")[
        DSE MINI MOCK
      ]
    ]
    #v(3mm)
    #align(center)[
      #text(size: 14pt, font: "Times New Roman", weight: "bold")[
        FOR S5 MATH
      ]
    ]
    #v(3mm)
    #align(center)[
      #text(size: 12pt, font: "Times New Roman", weight: "bold")[
        COMPULSORY PART
      ]
    ]
    #v(3mm)
    #align(center)[
      #text(size: 12pt, font: "Times New Roman")[
        PAPER 1
      ]
    ]
    #v(3mm)
    #align(center)[
      #text(size: 10pt, font: "Times New Roman")[
        (SET 1)
      ]
    ]

    #v(8mm)

    #align(center)[
      #text(size: 11pt, font: "Times New Roman", weight: "bold")[
        MATHEMATICS — Compulsory Part
      ]
    ]
    #v(2mm)
    #align(center)[
      #text(size: 10pt, font: "Times New Roman")[
        PAPER 1 (SET 1) · Question-Answer Book · (21/4 hours)
      ]
    ]
    #v(2mm)
    #align(center)[
      #text(size: 10pt, font: "Times New Roman", style: "italic")[
        This paper must be answered in English
      ]
    ]

    #v(6mm)

    #box(
      width: 100%,
      fill: rgb("#F0F0F0"),
      inset: (x: 4mm, y: 3mm),
      stroke: (thickness: 0.5pt, paint: gray),
    )[
      #text(size: 10pt, font: "Times New Roman", weight: "bold")[INSTRUCTIONS]
      #v(2mm)

      #text(size: 9pt, font: "Times New Roman")[1. Write your Name, Class and Class Number in the spaces provided on Page 1.]
      #v(1.5mm)
      #text(size: 9pt, font: "Times New Roman")[2. This paper consists of THREE sections, A(1), A(2) and B.]
      #v(1.5mm)
      #text(size: 9pt, font: "Times New Roman")[3. Attempt ALL questions in this paper. Write your answers in the spaces provided in this Question-Answer Book. Do not write in the margins. Answers written in the margins will not be marked.]
      #v(1.5mm)
      #text(size: 9pt, font: "Times New Roman")[4. Graph paper and supplementary answer sheets will be supplied on request. Write your Name and mark the question number box on each sheet, and fasten them with string INSIDE this book.]
      #v(1.5mm)
      #text(size: 9pt, font: "Times New Roman")[5. Unless otherwise specified, all working must be clearly shown.]
      #v(1.5mm)
      #text(size: 9pt, font: "Times New Roman")[6. Unless otherwise specified, numerical answers should be either exact or correct to 3 significant figures.]
      #v(1.5mm)
      #text(size: 9pt, font: "Times New Roman")[7. The diagrams in this paper are not necessarily drawn to scale.]
    ]

    #v(6mm)

    #grid(
      columns: (35mm, 1fr, 1fr),
      column-gutter: 8mm,
      row-gutter: 3mm,
      [
        #text(size: 9pt, font: "Times New Roman")[Name]
        #box(width: 100%, height: 6mm, stroke: (bottom: (thickness: 0.8pt, paint: black)))[]
        none,
      ],
      [
        #text(size: 9pt, font: "Times New Roman")[Class #( )]
        none, none,
      ],
      [
        #text(size: 9pt, font: "Times New Roman")[Marker's Use Only]
        #box(width: 100%, height: 6mm, stroke: (bottom: (thickness: 0.8pt, paint: black)))[]
        none,
      ],
      [
        #text(size: 9pt, font: "Times New Roman")[Examiner's Use Only]
        none, none,
      ],
      [
        #text(size: 9pt, font: "Times New Roman")[Marker No.]
        #box(width: 100%, height: 6mm, stroke: (bottom: (thickness: 0.8pt, paint: black)))[]
        #text(size: 9pt, font: "Times New Roman")[Examiner No.]
      ],
    )

    #v(4mm)

    #text(size: 9pt, font: "Times New Roman", weight: "bold")[Question No.]
    #v(1mm)

    #table(
      columns: (10mm,)*19,
      stroke: (thickness: 0.4pt, paint: gray),
      inset: (x: 0.5mm, y: 1mm),
      table.header(
        align(center)[#text(size: 7pt, font: "Times New Roman")[1]],
        align(center)[#text(size: 7pt, font: "Times New Roman")[2]],
        align(center)[#text(size: 7pt, font: "Times New Roman")[3]],
        align(center)[#text(size: 7pt, font: "Times New Roman")[4]],
        align(center)[#text(size: 7pt, font: "Times New Roman")[5]],
        align(center)[#text(size: 7pt, font: "Times New Roman")[6]],
        align(center)[#text(size: 7pt, font: "Times New Roman")[7]],
        align(center)[#text(size: 7pt, font: "Times New Roman")[8]],
        align(center)[#text(size: 7pt, font: "Times New Roman")[9]],
        align(center)[#text(size: 7pt, font: "Times New Roman")[10]],
        align(center)[#text(size: 7pt, font: "Times New Roman")[11]],
        align(center)[#text(size: 7pt, font: "Times New Roman")[12]],
        align(center)[#text(size: 7pt, font: "Times New Roman")[13]],
        align(center)[#text(size: 7pt, font: "Times New Roman")[14]],
        align(center)[#text(size: 7pt, font: "Times New Roman")[15]],
        align(center)[#text(size: 7pt, font: "Times New Roman")[16]],
        align(center)[#text(size: 7pt, font: "Times New Roman")[17]],
        align(center)[#text(size: 7pt, font: "Times New Roman")[18]],
        align(center)[#text(size: 7pt, font: "Times New Roman")[19]],
      ),
      align(center)[#text(size: 7pt, font: "Times New Roman")[]],
      align(center)[#text(size: 7pt, font: "Times New Roman")[]],
      align(center)[#text(size: 7pt, font: "Times New Roman")[]],
      align(center)[#text(size: 7pt, font: "Times New Roman")[]],
      align(center)[#text(size: 7pt, font: "Times New Roman")[]],
      align(center)[#text(size: 7pt, font: "Times New Roman")[]],
      align(center)[#text(size: 7pt, font: "Times New Roman")[]],
      align(center)[#text(size: 7pt, font: "Times New Roman")[]],
      align(center)[#text(size: 7pt, font: "Times New Roman")[]],
      align(center)[#text(size: 7pt, font: "Times New Roman")[]],
      align(center)[#text(size: 7pt, font: "Times New Roman")[]],
      align(center)[#text(size: 7pt, font: "Times New Roman")[]],
      align(center)[#text(size: 7pt, font: "Times New Roman")[]],
      align(center)[#text(size: 7pt, font: "Times New Roman")[]],
      align(center)[#text(size: 7pt, font: "Times New Roman")[]],
      align(center)[#text(size: 7pt, font: "Times New Roman")[]],
      align(center)[#text(size: 7pt, font: "Times New Roman")[]],
      align(center)[#text(size: 7pt, font: "Times New Roman")[]],
      align(center)[#text(size: 7pt, font: "Times New Roman")[]],
    )

    #v(1fr)

    #align(center + bottom)[
      #text(size: 7pt, font: "Times New Roman", fill: gray)[
        © Oxford University Press 2024
      ]
    ]
  ]
}

// ------------------------------------------------------------
// END PAGE
// ------------------------------------------------------------
#let fmt-end-page = {
  page(
    paper: "a4",
    margin: (top: MT, bottom: MT, left: ML, right: ML),
    header: none,
    footer: none,
  )[
    #v(10mm)
    #align(center + horizon)[
      #text(size: 14pt, font: "Times New Roman", weight: "bold")[
        END OF PAPER
      ]
    ]
    #v(5mm)
    #align(center)[
      #text(size: 7pt, font: "Times New Roman", fill: gray)[
        © Oxford University Press 2024
      ]
    ]
  ]
}

// ------------------------------------------------------------
// QUESTION PAGE  (reusable template for each section)
// page-start: first page number of this section
// sec: section data dict from exam-content
// pages-total: total pages in the paper (for footer)
// ------------------------------------------------------------
#let fmt-question-page(page-start, sec, pages-total) = {
  page(
    paper: "a4",
    margin: (top: MT, bottom: MT, left: ML, right: ML),
    header: none,
    footer: {
      place(bottom + right, dy: -4mm)[
        #text(size: 8pt, font: "Times New Roman", fill: gray)[
          #context counter(page).display() of #{pages-total}
        ]
      ]
    },
  )[
    #v(-3mm)
    #fmt-section-header(sec.section-label, sec.section-marks)
    // Render all questions in this section
    #for q in sec.questions {
      fmt-question(q.qnum, q.marks, q.body)
      // Margin warning only between questions, not after the last
    }
  ]
}

// ------------------------------------------------------------
// ASSEMBLE FULL PAPER
// ------------------------------------------------------------
#let make-paper = {
  import "content.typ": exam-content

  let pages-total = 24

  fmt-cover

  // ---- SECTION A(1) ----
  fmt-question-page(1, exam-content.at(0), pages-total)

  // ---- SECTION A(2) ----
  {
    page(
      paper: "a4",
      margin: (top: MT, bottom: MT, left: ML, right: ML),
      header: none,
      footer: {
        place(bottom + right, dy: -4mm)[
          #text(size: 8pt, font: "Times New Roman", fill: gray)[
            #context counter(page).display() of #{pages-total}
          ]
        ]
      },
    )[
      #v(-3mm)
      #fmt-section-header(exam-content.at(1).section-label, exam-content.at(1).section-marks)
      #for q in exam-content.at(1).questions {
        fmt-question(q.qnum, q.marks, q.body)
      }
    ]
  }

  // ---- SECTION B ----
  {
    page(
      paper: "a4",
      margin: (top: MT, bottom: MT, left: ML, right: ML),
      header: none,
      footer: {
        place(bottom + right, dy: -4mm)[
          #text(size: 8pt, font: "Times New Roman", fill: gray)[
            #context counter(page).display() of #{pages-total}
          ]
        ]
      },
    )[
      #v(-3mm)
      #fmt-section-header(exam-content.at(2).section-label, exam-content.at(2).section-marks)
      #for q in exam-content.at(2).questions {
        fmt-question(q.qnum, q.marks, q.body)
      }
    ]
  }

  fmt-end-page
}

