input.contents:
// ============================================================
// DSE Mini Mock — Style Library
// ============================================================

#let ML = 20mm
#let MT = 18mm

// ------------------------------------------------------------
// ANSWER SPACE  (generates ruled lines, default 5)
// ------------------------------------------------------------
#let answer-space(n: 5) = {
  for _ in range(n) {
    line(length: 100%, stroke: (thickness: 0.4pt, paint: gray, dash: "dotted"))
    v(3mm)
  }
}

// ------------------------------------------------------------
// QUESTION FORMATTER
// ------------------------------------------------------------
#let fmt-question(qnum, marks, body) = {
  [
    #text(size: 10pt, font: "Times New Roman", weight: "bold")[
      Q#{qnum}.
    ]
    #body
    #h(1fr)
    #text(size: 9pt, font: "Times New Roman")[(#{marks} marks)]
    #v(4mm)
    #answer-space(n: if marks <= 3 { 4 } else if marks <= 5 { 5 } else { 6 })
  ]
}

// ------------------------------------------------------------
// SECTION HEADER
// ------------------------------------------------------------
#let fmt-section-header(section-label, section-marks) = {
  [
    #v(3mm)
    #text(size: 11pt, font: "Times New Roman", weight: "bold")[
      Section #{section-label} (#{section-marks} marks)
    ]
    #v(2mm)
    #line(length: 100%, stroke: (thickness: 0.8pt, paint: black))
    #v(2mm)
  ]
}

// ------------------------------------------------------------
// COVER PAGE
// ------------------------------------------------------------
#let fmt-cover = {
  page(
    paper: "a4",
    margin: (top: 12mm, bottom: 12mm, left: ML, right: ML),
    header: none,
    footer: none,
  )[
    // Name / Class table — 2x2 bordered grid, top right corner
    #align(right + top)[
      #table(
        columns: (auto, 42mm),
        align: (left + horizon, left + horizon),
        stroke: (thickness: 0.6pt, paint: black),
        inset: (x: 1.5mm, y: 1.5mm),
        row-gutter: 0mm,
        column-gutter: 0mm,
      )[
        #text(size: 11pt, font: "Times New Roman", weight: "bold")[Name:]
        #text(size: 11pt, font: "Times New Roman")[ ]
      ][
        #text(size: 11pt, font: "Times New Roman", weight: "bold")[Class:]
        #text(size: 11pt, font: "Times New Roman")[ ]
      ]
    ]

    #v(15mm)

    // Title block centered
    #align(center)[
      #text(size: 28pt, font: "Times New Roman", weight: "bold")[Final Exam Mock 1]
    ]
    #v(5mm)
    #align(center)[
      #text(size: 18pt, font: "Times New Roman", weight: "bold")[Form 1 Mathematics]
    ]
    #v(3mm)
    #align(center)[
      #text(size: 14pt, font: "Times New Roman")[Paper 1 — Question-Answer Book]
    ]
    #v(3mm)
    #align(center)[
      #text(size: 12pt, font: "Times New Roman", style: "italic")[This paper must be answered in English,]
    ]

    #v(6mm)

    #box(
      fill: rgb("#F5F5F5"),
      inset: (x: 4mm, y: 3mm),
      stroke: (thickness: 0.6pt, paint: black),
      width: 100%,
    )[
      #text(size: 11pt, font: "Times New Roman", weight: "bold")[INSTRUCTIONS]
      #v(2mm)
      #set par(justify: false)
      #set text(size: 10pt, font: "Times New Roman")
      1. Write your Name and Class in the spaces provided at the top of this page.
      #v(1mm)
      2. This paper consists of THREE sections, A(1), A(2) and B.
      #v(1mm)
      3. Attempt ALL questions in this paper. Write your answers in the spaces provided in this Question-Answer Book. Do not write in the margins.
      #v(1mm)
      4. Graph paper and supplementary answer sheets will be supplied on request. Write your Name and mark the question number box on each sheet, and fasten them with string INSIDE this book.
      #v(1mm)
      5. Unless otherwise specified, all working must be clearly shown.
      #v(1mm)
      6. Unless otherwise specified, numerical answers should be either exact or correct to 3 significant figures.
      #v(1mm)
      7. The diagrams in this paper are not necessarily drawn to scale.
    ]

    #align(center + bottom)[
      #text(size: 9pt, font: "Times New Roman", fill: rgb("#555555"))[Mr. Thomas Yeung 2026]
    ]
  ]
}

// ------------------------------------------------------------
// END PAGE
// ------------------------------------------------------------
#let fmt-end-page = {
  page(
    paper: "a4",
    margin: (top: MT, bottom: MT, left: ML, right: ML),
    header: none,
    footer: none,
  )[
    #v(10mm)
    #align(center + horizon)[
      #text(size: 14pt, font: "Times New Roman", weight: "bold")[
        END OF PAPER
      ]
    ]
    #v(5mm)
    #align(center)[
      #text(size: 7pt, font: "Times New Roman", fill: gray)[
        © Oxford University Press 2024
      ]
    ]
  ]
}

// ------------------------------------------------------------
// QUESTION PAGE  (reusable template for each section)
// page-start: first page number of this section
// sec: section data dict from exam-content
// pages-total: total pages in the paper (for footer)
// ------------------------------------------------------------
#let fmt-question-page(page-start, sec, pages-total) = {
  page(
    paper: "a4",
    margin: (top: MT, bottom: MT, left: ML, right: ML),
    header: none,
    footer: {
      place(bottom + right, dy: -4mm)[
        #text(size: 8pt, font: "Times New Roman", fill: gray)[
          #context counter(page).display() of #{pages-total}
        ]
      ]
    },
  )[
    #v(-3mm)
    #fmt-section-header(sec.section-label, sec.section-marks)
    // Render all questions in this section
    #for q in sec.questions {
      fmt-question(q.qnum, q.marks, q.body)
      // Margin warning only between questions, not after the last
    }
  ]
}

// ------------------------------------------------------------
// ASSEMBLE FULL PAPER
// ------------------------------------------------------------
#let make-paper = {
  import "content.typ": exam-content

  let pages-total = 24

  fmt-cover

  // ---- SECTION A(1) ----
  fmt-question-page(1, exam-content.at(0), pages-total)

  // ---- SECTION A(2) ----
  {
    page(
      paper: "a4",
      margin: (top: MT, bottom: MT, left: ML, right: ML),
      header: none,
      footer: {
        place(bottom + right, dy: -4mm)[
          #text(size: 8pt, font: "Times New Roman", fill: gray)[
            #context counter(page).display() of #{pages-total}
          ]
        ]
      },
    )[
      #v(-3mm)
      #fmt-section-header(exam-content.at(1).section-label, exam-content.at(1).section-marks)
      #for q in exam-content.at(1).questions {
        fmt-question(q.qnum, q.marks, q.body)
      }
    ]
  }

  // ---- SECTION B ----
  {
    page(
      paper: "a4",
      margin: (top: MT, bottom: MT, left: ML, right: ML),
      header: none,
      footer: {
        place(bottom + right, dy: -4mm)[
          #text(size: 8pt, font: "Times New Roman", fill: gray)[
            #context counter(page).display() of #{pages-total}
          ]
        ]
      },
    )[
      #v(-3mm)
      #fmt-section-header(exam-content.at(2).section-label, exam-content.at(2).section-marks)
      #for q in exam-content.at(2).questions {
        fmt-question(q.qnum, q.marks, q.body)
      }
    ]
  }

  fmt-end-page
}
